## Code Example
```javascript
function routeForTenant(tenant, models, estimates, budgets){
  // pick fastest model within budget and privacy constraints
  const allowed = models.filter(m => tenant.allowedModels.includes(m.name) && m.privacyOK === true);
  const feasible = allowed.filter(m => estimates[m.name] <= tenant.latencyBudgetMs);
  return feasible.sort((a,b) => estimates[a.name]-estimates[b.name])[0] || null;
}
```

